  b('act','מהי סמיכה ומתי היא נעשית','סמיכה נעשית על ראש הקרבן בשתי ידיים, בידי מי שחייב לסמוך. סומכים במקום השחיטה בעזרה, ותכף לסמיכה שחיטה: אין להפסיק במעשה אחר בין השתיים. ההסבר כאן עוסק בסמיכת קרבנות הבהמה, ואינו תיאור של ארבע עבודות הדם.',[('av-mm-9.8',[1]),('av-m-9.8',[1])]),
  b('offerings','אילו קרבנות טעונים סמיכה','בקרבנות היחיד שהמשנה מונה נוהגת סמיכה, חוץ מבכור, מעשר ופסח. בציבור המשנה מונה פר הבא על כל המצוות ושעיר המשתלח; הרמב״ם מפרש שהפר כאן הוא פר העלם דבר של ציבור. רבי שמעון מוסיף שעירי עבודה זרה, והרמב״ם אינו פוסק כמותו.',[('av-mm-9.7',[1]),('av-m-9.7',[1])]),
  b('person','מי סומך','אין שליח סומך במקום הבעלים, ואין אחד מן השותפים סומך עבור כל חבריו. המשנה מונה גם את הפטורים מסמיכה, ובהם אשה, קטן וחרש ושוטה. אין ללמוד מדין שחיטה בזר שגם כל מעשה אחר של הקרבן יכול להיעשות בידי כל אדם.',[('av-mm-9.8',[1]),('av-m-9.8',[1]),('av-mm-9.9',[1])]),
  b('effect','מצוה שאינה מעכבת כפרה','הרמב״ם מפרש ״שיירי מצוה״: אם לא סמך כבר כיפר, אף שמעלה עליו כאילו לא כיפר. פירוש הדבר אינו שהסמיכה רשות, אלא שיש להבחין בין חיסרון המצוה לבין עיכוב הכפרה.',[('av-m-9.8',[1])],links=['av-shechitah','av-tenufah'])
