  b('act','מהי הולכה','הולכת הדם היא הבאת הדם שהתקבל מן הזבח אל מקום מתנתו במזבח. היא נמנית בין ארבע העבודות, ואף היא טעונה כהן; הרמב״ם מדגיש שהולכה בזר פסולה.',[('av-z-1.4',[1]),('av-mz-1.4',[1])]),
  b('possible','עבודה שאפשר לבטלה','המשנה מביאה את רבי שמעון המבחין בהולכה מפני שאפשר לשחוט בצד המזבח ולזרוק בלי צורך בהילוך זה. חכמים אומרים שגם עבודה שאפשר לבטלה שמה עבודה, והרמב״ם פוסק כמותם. האפשרות לתכנן את הסדר בלא הולכה אינה מבטלת את דיניה כשהיא נעשית.',[('av-mz-1.4',[1]),('av-z-1.4',[1])]),
