  b('inner','עבודת דם החטאות הפנימיות','בפר ושעיר של יום הכפורים יש הזאות בין הבדים, על הפרוכת ועל מזבח הזהב. בפרים ובשעירים הנשרפים נמנות הזאות על הפרוכת ועל מזבח הזהב. אין להפוך את השם ״חטאת פנימית״ לתיאור אחד של כל מקומות ההזאה.',[('mishnah5',[1,2]),('z5-1',[1])]),
  b('meakev','מספר המתנות: מצוה ועיכוב','מספר המתנות לכתחילה אינו תמיד מספר המתנות המעכבות כפרה. בנתנין על מזבח החיצון, בית הלל אומרים שאף בחטאת מתנה אחת כיפרה, והרמב״ם סומך על דעתם. בנתנין על המזבח הפנימי, חסרון מתנה מעכב. אין ללמוד מכפרה בדיעבד שמותר לדלג על שאר המתנות לכתחילה.',[('av-mz-4.1',[1]),('av-z-4.1',[1]),('av-mz-4.2',[1]),('av-z-4.2',[1])]),
