  b('altar','אם עלה לא ירד','דין ״המזבח מקדש את הראוי לו״ אינו מתיר להעלות כל דבר למזבח. הרמב״ם מדגים שקומץ שלא נתקדש בכלי שרת אינו מתקדש מכוח עלייתו בלבד. הוא פוסק כרבי יהושע במחלוקתו עם רבן גמליאל; פרטי הפסולים שדינם לירד או שלא לירד טעונים בירור נוסף.',[('av-mz-9.1',[1]),('av-z-9.1',[1])],links=['imurim','olah','minchah'])
