  b('blood','הזאה ומיצוי','בחטאת העוף מזים למטה על קיר המזבח, ושיירי הדם מתמצים ליסוד. בעולת העוף ממצים את הדם על הקיר למעלה. החילוק אינו רק בכמות הדם: זהו סדר עבודה אחר ומקום אחר.',[('mishnah6',[4,5]),('z6-4',[1]),('z6-5',[1])]),
